# area: generics_variance
# hypothesis: PEP 695 infers covariance for a read-only generic box so Box[Dog] is accepted as Box[Animal], while a mutable list[Dog] is rejected as list[Animal] and a bounded TypeVar rejects non-Animal arguments.
from typing import Callable, reveal_type


class Animal:
    def name(self) -> str:
        return 'animal'


class Dog(Animal):
    def name(self) -> str:
        return 'dog'


class ReadOnlyBox[T]:
    def __init__(self, item: T) -> None:
        self._item = item

    def get(self) -> T:
        return self._item


def logged[T](fn: Callable[[T], str]) -> Callable[[T], str]:
    def wrapper(x: T) -> str:
        return fn(x)
    return wrapper


@logged
def describe(a: Animal) -> str:
    return a.name()


def first_name[A: Animal](items: list[A]) -> str:
    return items[0].name()


def take_animal_box(b: ReadOnlyBox[Animal]) -> str:
    return b.get().name()


def add_animal(xs: list[Animal]) -> None:
    xs.append(Animal())


def unsafe_add() -> int:
    dogs: list[Dog] = [Dog()]
    add_animal(dogs)  # expect-error: list is invariant
    return len(dogs)


def bad_bound() -> str:
    try:
        return first_name(['x'])  # expect-error: str is not an Animal
    except AttributeError:
        return 'AttributeError'


boxed = ReadOnlyBox(Dog())
reveal_type(take_animal_box(boxed))
reveal_type(describe(Dog()))
reveal_type(unsafe_add())
reveal_type(bad_bound())
